import fs from 'node:fs';
import path from 'node:path';

const ROOT=path.resolve(import.meta.dirname,'..');
const OUT=path.join(ROOT,'assets/assessment-banks/year4/english');
const mk=(c,g,b,d,r,h)=>({c,g,b,d,r,h});
const P={
AC9E4LA01:{t:'Language for Formal and Informal Relationships',s:'choose language that suits the relationship, purpose and situation',x:[
mk('emailing the school principal to ask about assembly times','Could you please let me know what time the assembly begins?','Hey, what time is the thing?','Tell me the assembly time now.','The polite request suits a formal relationship without using complicated language.','Think about who is receiving the message and how well you know them.'),
mk('asking a close friend to bring a football to the park','Can you bring the footy this arvo?','Dear Sir or Madam, I respectfully request the football.','Bring it or else.','A relaxed expression can suit a close friendship while still being respectful.','Informal does not mean rude; it means the language can be more relaxed.'),
mk('welcoming an Elder who is visiting the class','Welcome, Aunty May. Thank you for sharing your knowledge with us.','Hey May, tell us your stories.','Oi, come and sit here.','Respectful address and thanks recognise the relationship and cultural protocol.','Notice the respectful form of address and the acknowledgement of the visitor.'),
mk('asking a librarian for help finding a book','Excuse me, could you help me find this title, please?','Move, I need that shelf.','Mate, grab me that book.','The request is courteous and suitable for an adult you may not know well.','Choose language that is clear, polite and appropriate to the relationship.'),
mk('disagreeing with a teammate during a lunchtime game','I see it differently. Can we check the rule together?','You are wrong, so stop talking.','Whatever. Your idea is silly.','Respectful disagreement protects the relationship while still expressing a different view.','Look for wording that disagrees without attacking the person.'),
mk('asking a museum guide a question on an excursion','Excuse me, may I ask how old this canoe is?','Hey, how old is that thing?','Answer me about the canoe.','A courteous question suits an unfamiliar adult in a public setting.','Test whether the wording would sound respectful to someone you have just met.'),
mk('sending a message to a cousin about a weekend barbecue','Are you coming to the barbie on Saturday?','To whom it may concern, please confirm attendance.','You must attend the barbecue.','Friendly, relaxed wording suits a familiar family relationship.','Choose a tone that matches a cousin rather than a formal organisation.') ]},
AC9E4LA02:{t:'Subjective and Objective Language',s:'separate factual reporting from opinion and feeling',x:[
mk('reporting the result of a class plant investigation','The bean plant grew 6 centimetres in seven days.','The bean plant grew amazingly fast.','I loved how tall the bean plant became.','The sentence gives a measurable observation rather than a judgement or feeling.','Look for information that could be checked or measured.'),
mk('reviewing a new playground','The new climbing frame is exciting and much better than the old one.','The climbing frame is 2.4 metres high.','The playground opened on Monday.','Words such as exciting and better express a personal judgement.','Opinion words reveal what someone thinks or feels.'),
mk('describing a local weather reading','At 3 pm the temperature was 19°C.','The afternoon was horribly cold.','It felt like the worst weather all week.','A temperature reading is observable data, unlike an emotional judgement.','Ask whether another observer could verify the same fact.'),
mk('writing about a school concert','In my view, the choir gave the most moving performance.','The choir sang three songs.','The concert began at 6:30 pm.','The phrase in my view signals that the statement is an opinion.','Notice phrases that openly show a viewpoint.'),
mk('summarising a council notice about water restrictions','The notice says garden sprinklers may be used before 10 am.','The council has made a ridiculous rule.','Everyone will hate these restrictions.','The sentence reports what the notice states without adding a judgement.','Separate what the source says from how someone feels about it.'),
mk('writing a review of a wildlife documentary','The underwater footage is breathtaking.','The program runs for 48 minutes.','The film includes footage of coral reefs.','Breathtaking evaluates the footage and shows the writer’s response.','Look for language that judges quality.'),
mk('recording a sports carnival result','Mia finished the 100-metre race in 16.2 seconds.','Mia ran brilliantly.','Mia was clearly the most impressive athlete.','The time is a checkable result, while brilliantly and impressive are evaluations.','Choose the statement based on recorded evidence.') ]},
AC9E4LA03:{t:'Text Structures and Language Across the Curriculum',s:'match text organisation and language to purpose',x:[
mk('writing a science report about evaporation','Use a question or aim, method, observations and conclusion with measured results.','Tell the event as a fantasy quest.','List jokes in random order.','A science report needs stages that show what was investigated, what happened and what the evidence means.','Match the organisation to what the reader needs to learn from the investigation.'),
mk('writing instructions for making damper','Use a goal, ingredients and ordered steps with command verbs such as mix and bake.','Use a complication and resolution.','Write one long paragraph with no sequence.','Procedures guide action, so ordered steps and command verbs make the process usable.','Ask what a reader must do first, next and last.'),
mk('writing a history recount of a community event','Present events in time order using dates and past-tense verbs.','Group facts by rhyme.','Begin with a recipe and finish with a weather chart.','A recount makes the sequence of past events clear.','Look for time order and language that locates events in the past.'),
mk('writing a geography report about the Murray River','Group information under topic headings and use place names and geographical terms.','Use only dialogue between imaginary characters.','Hide all facts inside a poem.','Topic sections and subject vocabulary help readers find and understand geographical information.','Choose features that organise information rather than entertain for their own sake.'),
mk('writing a health poster about sun safety','Use a strong heading, brief action points and direct advice such as wear a hat.','Use a long narrative with no headings.','Put the main advice in tiny print at the bottom.','A poster must communicate actions quickly and clearly.','Think about how a reader scans a poster.'),
mk('preparing a museum information panel about fossils','Use a heading, short factual sections, labelled images and scientific terms explained clearly.','Use a diary entry with unrelated feelings.','Use only a list of character names.','An information panel combines organised facts and visual labels so visitors can understand the display quickly.','Match structure, language and layout to a public information purpose.'),
mk('writing a maths explanation of how to find perimeter','State the idea, show an example and explain each step using precise mathematical terms.','Use a suspenseful plot twist.','Describe the writer’s weekend instead.','A maths explanation needs logical steps and precise vocabulary so the reasoning can be followed.','Choose a structure that makes the method visible.') ]},
AC9E4LA04:{t:'Connectives and Topic Cohesion',s:'connect ideas with accurate connectives and clear topic links',x:[
mk('explaining how a seed germinates','First, the seed absorbs water. Then, the root begins to grow.','First, the seed absorbs water. However, the root begins to grow.','The seed absorbs water. Football is popular.','First and then show a clear time sequence between related ideas.','Choose a connective that matches the relationship between the ideas.'),
mk('explaining why the oval was closed after heavy rain','The ground was waterlogged; therefore, the oval was closed.','The ground was waterlogged; meanwhile, the oval was closed.','The ground was waterlogged; for example, the oval was closed.','Therefore shows that the closure is a result of the waterlogged ground.','Ask whether the second idea is a result, contrast, example or time event.'),
mk('adding another reason to a persuasive paragraph about shade','In addition, more shade would make lunchtime areas cooler.','However, more shade would make lunchtime areas cooler.','Finally, because more shade would.','In addition signals another supporting point on the same topic.','Notice whether the writer is adding, contrasting or concluding.'),
mk('linking a condition to an action in a bushwalk safety guide','If the track is closed, choose another route.','Although the track is closed, choose another route because maybe.','Before the track is closed, choose another route.','If introduces the condition that determines what action should follow.','Find the word that means this action depends on that situation.'),
mk('keeping a paragraph about koalas focused','Koalas rest in eucalyptus trees. These animals also feed on eucalyptus leaves.','Koalas rest in eucalyptus trees. They means the school bell.','Koalas rest in eucalyptus trees. My bike has new tyres.','These animals clearly refers back to koalas and keeps the topic chain connected.','Check that pronouns and related words point clearly to the same topic.'),
mk('connecting two ideas in a new article about recycling','The bins were clearly labelled; as a result, fewer items went into the wrong bin.','The bins were clearly labelled; on the other hand, fewer items went into the wrong bin.','The bins were clearly labelled; yesterday, fewer because.','As a result accurately shows a cause-and-effect relationship.','Test the logical link between the two clauses.'),
mk('ordering steps in an online safety checklist','Firstly, check the sender. Next, inspect the link. Finally, ask an adult if you are unsure.','However, check the sender. Therefore, inspect the link.','Check the sender. Pelicans live near water. Inspect the link.','The sequence words guide the reader through an ordered process while every sentence stays on topic.','Look for both logical order and topic consistency.') ]},
AC9E4LA05:{t:'Navigation and Readability in Online Texts',s:'use online navigation and layout features to find information efficiently',x:[
mk('finding excursion permission information on a school website','Open the Excursions heading, then choose the Permission forms link.','Click a link labelled Click here with no clue where it goes.','Scroll randomly through every page.','Descriptive headings and links tell the reader where information is likely to be.','Choose the feature whose label predicts the destination.'),
mk('checking tomorrow’s forecast on a weather website','Use the location search box and select the correct town.','Open an unrelated advertisement.','Keep refreshing the home page without choosing a location.','A search box is designed to take the reader directly to a named location or topic.','Match the navigation tool to the information you need.'),
mk('reading a long online article about coral reefs','Use subheadings to jump to the section about reef animals.','Ignore all headings and begin in the middle.','Choose the biggest decorative photo even if it is unrelated.','Subheadings divide information into named sections that can be scanned.','Look for a feature that helps you predict what each section contains.'),
mk('moving back from a museum object page to the Ancient Egypt collection','Use the breadcrumb trail showing Home > Collections > Ancient Egypt > Object.','Close the browser and search the whole web again.','Click a decorative logo with no label.','Breadcrumbs show where the current page sits inside the site and provide a path back.','Notice which feature shows the page hierarchy.'),
mk('making a class webpage easier to read on a tablet','Place the main heading first, use short sections and keep buttons large and clearly labelled.','Put every link in one tiny block of text.','Cover the article with unrelated animations.','Readable layout creates a clear order and makes controls easy to identify and use.','Think about what the reader should notice and tap first.'),
mk('finding opening hours on a zoo website','Choose the Visit menu, then the Opening hours link.','Click every animal photo until a time appears.','Use a link labelled More without checking its destination.','A clear menu path reduces searching because each label narrows the information.','Follow labels that describe the information you are looking for.'),
mk('improving an online bushfire safety page','Use a clear Emergency advice heading, short paragraphs and a labelled link to current alerts.','Use pale text on a busy photo background.','Hide current alerts behind an unlabeled icon.','Strong visual hierarchy and descriptive links help readers find urgent information quickly.','Prioritise the information readers may need first.') ]},
AC9E4LA06:{t:'Complex Sentences: Independent and Dependent Clauses',s:'build complex sentences by linking independent and dependent clauses',x:[
mk('explaining why the class stayed inside at lunch','Because the rain was heavy, the class stayed inside.','Because the rain was heavy.','The class stayed inside and the rain.','Because the rain was heavy cannot stand alone here, so it depends on the complete clause the class stayed inside.','Find the part that can stand alone as a complete message.'),
mk('showing time in a sentence about a kookaburra','When the sun rose, the kookaburra called from the fence.','When the sun rose.','The kookaburra called and when.','When introduces a dependent time clause that tells when the main event happened.','Ask what relationship the joining word creates.'),
mk('showing a condition for going to the beach','We will swim if the flags show it is safe.','We will swim because the flags show it is safe, even when they do not.','If the flags show it is safe.','If introduces the condition that must be met for the swimming plan.','Look for a condition rather than a cause or time.'),
mk('showing cause in a sentence about a cancelled game','The match was cancelled because lightning was nearby.','The match was cancelled although lightning caused the danger.','Because lightning was nearby.','Because connects the result to its cause while the independent clause can stand alone.','Identify which idea explains why the other happened.'),
mk('adding contrast to a sentence about a bushwalk','Although the track was steep, the group reached the lookout.','Because the track was steep, the group reached the lookout.','Although the track was steep.','Although shows an unexpected contrast between the steep track and the successful climb.','Test whether the ideas show cause, time, condition or contrast.'),
mk('combining ideas about a science experiment','After the ice melted, we measured the water.','After the ice melted.','We measured because after the ice.','After introduces a dependent time clause and the main clause completes the sentence.','Check that the sentence has one complete clause plus the added time detail.'),
mk('writing a safety instruction for a storm','Stay indoors until the thunderstorm has passed.','Until the thunderstorm has passed.','Stay indoors and until thunderstorm.','Until creates a time relationship and depends on the independent command stay indoors.','A dependent clause adds detail but usually cannot stand alone.') ]},
AC9E4LA07:{t:'Quoted and Reported Speech',s:'distinguish direct quotation from reported speech and use each accurately',x:[
mk('quoting the coach after a netball game','The coach said, “We kept trying until the final whistle.”','The coach said that “we kept trying until the final whistle”.','The coach we kept trying until the final whistle.','Quotation marks show the coach’s exact spoken words.','Use quotation marks only when the wording is presented as the speaker’s exact words.'),
mk('reporting what the coach said without quoting','The coach said that the team had kept trying until the final whistle.','The coach said, “that the team had kept trying”.','“The coach said that the team kept trying.”','Reported speech retells the message without quotation marks and may adjust pronouns or tense.','Check whether the sentence gives exact words or reports the idea.'),
mk('turning “I will bring my hat tomorrow,” Mia said, into reported speech','Mia said that she would bring her hat the next day.','Mia said that I will bring my hat tomorrow.','Mia said, she would bring her hat tomorrow.','Reported speech changes I to she and tomorrow to the next day because the viewpoint and time reference shift.','Track pronouns, tense and time words when the speaker’s words are retold.'),
mk('choosing a reporting verb for a strong promise','Luca promised that he would return the library book.','Luca whispered that he would return it, even though the sentence is about a promise.','Luca happened the library book.','Promised tells the reader what kind of speech act Luca made, not just that he spoke.','Choose a reporting verb that matches the meaning of the original speech.'),
mk('using a quotation in a school news report','Asha said, “The new garden gives us a cooler place to read.”','Asha said the new garden gives us “a cooler place” without showing whether those were her exact words.','The new garden Asha said cooler place.','A direct quotation should preserve the speaker’s wording and clearly identify who spoke.','Check that the quoted words are exact and the speaker is named.'),
mk('summarising a scientist’s explanation','Dr Chen explained that the frog population had increased after the wet summer.','Dr Chen, “the frog population had increased after the wet summer”.','Dr Chen explained “that the frog population”.','Reported speech is useful when the writer wants the information rather than every exact word.','Notice that reported speech normally has no quotation marks around the message.'),
mk('changing a direct question into reported speech','Noah asked whether the bus would arrive soon.','Noah asked, “whether the bus would arrive soon”.','Noah asked whether will the bus arrive soon?','A reported question changes the word order and removes quotation marks around the reported message.','Do not keep direct-question word order when reporting the question.') ]},
AC9E4LA08:{t:'Adverb Groups and Prepositional Phrases',s:'add useful circumstances of time, place and manner',x:[
mk('adding place detail to “The wallaby hopped”','The wallaby hopped across the rocky track.','The wallaby rocky hopped.','Across hopped the wallaby track without a clear relationship.','Across the rocky track is a prepositional phrase telling where the hopping happened.','Look for a phrase that answers where, when or how.'),
mk('adding manner detail to “The choir sang”','The choir sang surprisingly softly.','The choir sang under the stage if the meaning is manner.','The choir softly surprising sang.','Surprisingly softly is an adverb group that tells how the choir sang.','Manner details explain how an activity happens.'),
mk('adding time detail to “We packed the tent”','We packed the tent before sunrise.','We packed before the tent sunrise.','We sunrise packed the tent.','Before sunrise is a prepositional phrase giving the time of the action.','Check what circumstance the phrase adds.'),
mk('placing a phrase so its meaning is clear','After lunch, the class visited the gallery.','The class, after, visited lunch the gallery.','The class visited after the gallery lunch.','Placing After lunch together makes it clear that the phrase tells when the visit happened.','Keep the phrase close to the activity it describes.'),
mk('adding a precise place detail to a science observation','The lizard rested beneath the warm rock.','The lizard rested warm.','The lizard beneath rested rock the.','Beneath the warm rock specifies where the lizard rested.','Choose detail that adds useful information, not just extra words.'),
mk('adding frequency to a routine','The library team checks the returns every afternoon.','The library team every checks afternoon the returns.','The library team checks the returns blue.','Every afternoon gives a repeated time circumstance for the activity.','Ask what detail helps the reader understand when or how often.'),
mk('improving a sentence about a cyclist','The cyclist moved carefully around the fallen branch.','The cyclist moved branch carefully fallen.','The cyclist moved with around.','Carefully explains manner and around the fallen branch explains the route or place.','Useful circumstances should attach clearly to the action.') ]},
AC9E4LA09:{t:'Tense and Its Impact on Meaning',s:'use past, present and future tense to show time accurately',x:[
mk('recounting yesterday’s excursion','We visited the aquarium and watched the penguins.','We visit the aquarium yesterday and watch the penguins.','We will visit the aquarium yesterday.','Past-tense verbs match an event that already happened.','Use the time clue to decide which verb form fits.'),
mk('stating a general fact about water','Water freezes at 0°C under standard conditions.','Water froze at 0°C every time in general.','Water will freezing at 0°C.','Simple present is commonly used for general truths.','Present tense can describe facts, not only what is happening this second.'),
mk('describing a plan for next week','Our class will visit the botanic gardens next Thursday.','Our class visited the gardens next Thursday.','Our class visiting next Thursday without a finite verb.','Will visit places the event in the future and matches next Thursday.','Match the verb form to the stated time.'),
mk('writing about a regular Saturday activity','I play cricket at the oval every Saturday.','I played cricket every Saturday if the routine is still current.','I will played cricket every Saturday.','Simple present can describe a repeated habit.','Words such as every Saturday often signal a routine.'),
mk('correcting an irregular past-tense verb','Last night, we saw a meteor.','Last night, we seed a meteor.','Last night, we see a meteor.','Saw is the correct irregular past form of see.','Not every past-tense verb ends in -ed.'),
mk('shifting time clearly in a narrative','I packed my bag last night, and now I am waiting for the bus.','I pack my bag last night, and now I waited for the bus.','I will pack last night, and now I wait yesterday.','A tense shift is correct when the time frame clearly changes from last night to now.','Tense does not need to stay identical when the time changes.'),
mk('describing a future arrangement','We are meeting the ranger at 10 am tomorrow.','We met the ranger tomorrow.','We are met the ranger yesterday.','Present continuous can express a planned future arrangement when the time is clear.','Future time is not expressed only with will.') ]},
AC9E4LA10:{t:'Framing, Placement and Salience in Images',s:'explain how composition changes what viewers notice and infer',x:[
mk('designing a poster about protecting turtles','Place a large, sharply focused turtle near the centre and keep the background less detailed.','Make the turtle tiny in a crowded corner.','Crop the turtle out and enlarge an unrelated bin.','Size, central placement and sharp focus make the turtle more salient.','Ask what the viewer will notice first and why.'),
mk('cropping a photo of a crowded beach for a news story','Keep enough of the crowd and shoreline visible to show the scale of the scene.','Crop tightly around one empty patch so the beach looks deserted.','Remove the shoreline so the location is unclear.','Cropping can change the apparent meaning by including or excluding context.','Check what information disappears when the frame changes.'),
mk('showing a character as isolated in a film still','Place the character small and alone near the edge of a wide empty frame.','Fill the frame with a close-up group selfie.','Put many bright objects around the character so isolation disappears.','Distance, empty space and edge placement can make the character appear isolated.','Consider how position and surrounding space shape the response.'),
mk('making a warning symbol stand out on an information page','Use strong contrast and place the symbol close to the safety message.','Use the same pale colour as the background.','Place the symbol far from the warning text among decorations.','Contrast and proximity increase salience and connect the symbol to the warning.','Look at colour, size, position and closeness to related words.'),
mk('comparing two photographs of the same football match','The close-up of the goalkeeper emphasises emotion, while the wide shot shows team positions.','Both photos must mean exactly the same because they show the same match.','Only the camera brand changes the meaning.','Framing controls how much context is visible and therefore what the viewer focuses on.','Compare what each frame includes and leaves out.'),
mk('choosing a hero image for a wildlife webpage','Use a clear image of the featured bilby with the animal larger than background details.','Use a tiny bilby hidden behind text.','Use an unrelated city traffic photo as the largest image.','The featured subject should be visually salient so the image supports the page topic.','The most noticeable element should connect to the main purpose.'),
mk('editing a video scene to create suspense','Begin with a wide dark corridor, then cut to a close-up of the slowly turning door handle.','Show the solution immediately in a bright wide shot.','Keep every object equally large and equally bright.','Changing framing and salience can guide attention and delay information to build suspense.','Track what the viewer is allowed to see at each moment.') ]},
AC9E4LA11:{t:'Synonyms, Antonyms and Precise Vocabulary',s:'choose words with accurate shades of meaning',x:[
mk('replacing “walked” in “The exhausted hiker walked back to camp”','trudged','skipped','floated','Trudged suggests slow, heavy movement and matches an exhausted hiker.','A synonym must fit the exact context, not merely have a related dictionary meaning.'),
mk('choosing a stronger word than “looked” in “Mia looked at the tiny writing carefully”','examined','glanced','ignored','Examined means looked at closely and carefully.','Compare the intensity and purpose of the words.'),
mk('finding the best antonym of “scarce” in a sentence about rainfall','abundant','dry','tiny','In this context, abundant means plentiful, which contrasts with scarce.','Choose the opposite meaning that fits the same sense of the word.'),
mk('choosing precise science vocabulary','The liquid evaporated as it gained heat.','The liquid did a thing when it got hot.','The liquid vanished magically.','Evaporated precisely names the process being described.','Technical words can make meaning more exact when they are used correctly.'),
mk('choosing between “whispered”, “said” and “shouted”','The child whispered so the sleeping baby would not wake.','The child shouted so the sleeping baby would not wake.','The child exploded the sentence.','Whispered includes the idea of speaking very quietly, which fits the situation.','Synonyms often carry different intensity or manner.'),
mk('using a newly encountered First Nations Australian word accurately in context','After reading the local language guide, we used the word only with the meaning and spelling given by the source.','We guessed a meaning because the word sounded familiar.','We changed the spelling to make it look more English.','Words from First Nations Australian languages should be used with care, accurate meaning and respect for the source.','Check the source, language and meaning rather than guessing.'),
mk('revising “The storm was bad” for a vivid weather report','The storm was severe, with damaging wind gusts.','The storm was super-duper mega bad.','The storm was pleasant and damaging.','Severe is precise and appropriately strong for damaging conditions.','Choose precision rather than simply making a word longer or more dramatic.') ]},
AC9E4LA12:{t:'Punctuating Dialogue',s:'punctuate direct speech so speakers and sentence boundaries are clear',x:[
mk('punctuating a statement before a speech tag','“I found the missing hat,” Zara said.','“I found the missing hat”, Zara said.','“i found the missing hat,” Zara said.','The comma belongs before the closing quotation mark in this speech-tag pattern, and the spoken sentence begins with a capital.','Check the quotation marks, capital letter and punctuation before the speech tag.'),
mk('punctuating a question before a speech tag','“Are we leaving now?” Noah asked.','“Are we leaving now,” Noah asked?','“Are we leaving now?” Noah Asked.','The question mark belongs to the spoken question, and asked stays lowercase because the reporting clause continues the sentence.','A question mark can replace the comma before a following speech tag.'),
mk('starting a new speaker on a new line','“I packed the water,” Ava said.\n“Great,” Ben replied.','“I packed the water,” Ava said. “Great,” Ben replied.','“I packed the water, Ava said.\nGreat,” Ben replied.','A new paragraph helps readers see that a different person is speaking.','Track speaker changes as well as punctuation marks.'),
mk('punctuating a speech tag before the quotation','Dad called, “Dinner is ready!”','Dad called “Dinner is ready”!','Dad Called, “dinner is ready!”','A comma separates the speech tag from the quotation, and the spoken sentence begins with a capital letter.','Check punctuation on both sides of the opening quotation mark.'),
mk('punctuating dialogue followed by an action','“Wait here,” Priya said, pointing to the gate.','“Wait here”, Priya said pointing to the gate.','“Wait here.” Priya said, pointing to the gate.','The comma before the closing quotation mark links the speech to the following reporting clause.','Decide whether the words after the quote continue the same sentence.'),
mk('punctuating an exclamation before a speech tag','“Watch out!” Eli shouted.','“Watch out,” Eli shouted!','“Watch out!” Eli Shouted.','The exclamation mark belongs inside the quotation and the reporting verb remains lowercase.','Boundary punctuation inside the quote can replace a comma.'),
mk('writing two lines of dialogue with clear speakers','“Did you bring the map?” asked Ruby.\n“Yes, it is in my bag,” Sam replied.','“Did you bring the map”? asked Ruby. “Yes it is in my bag”, Sam replied.','Did you bring the map? “asked Ruby” Yes, it is in my bag.','Correct quotation marks, punctuation and paragraphing make the change of speaker easy to follow.','Read the exchange aloud and check each speaker’s exact words and sentence boundary.') ]},
AC9E4LE01:{t:'Literature Across Times and Cultures',s:'compare similar ideas, storylines and relationships across different literary contexts',x:[
mk('comparing two stories in which a child must leave home','Both stories explore separation, but the reasons for leaving and the family expectations are different.','The stories are identical because both characters travel.','Only the publication date matters.','A useful comparison identifies a genuine similarity and a meaningful difference shaped by context.','Compare what happens and why it matters in each story.'),
mk('comparing a traditional tale with a modern retelling','The retelling keeps the journey pattern but changes the setting and the character’s choices.','The retelling has no connection because the character names differ.','Every retelling must copy every event exactly.','Retellings can preserve a storyline pattern while adapting details for another audience or time.','Look for underlying patterns as well as changed details.'),
mk('comparing family relationships in two Australian novels','Both show care between generations, but one family expresses it through quiet actions and the other through direct conversation.','Both are the same because each book has a grandparent.','Neither can be compared because the families live in different places.','Relationships can be similar in purpose while being represented differently.','Use evidence about how characters act and speak.'),
mk('comparing a First Nations Australian story and another story about Country or place','Both texts show that place carries meaning, but each text must be understood in its own cultural context.','All stories about land mean exactly the same thing.','Cultural context should be ignored during comparison.','Respectful comparison recognises connections without flattening distinct cultural meanings.','Notice similarities, then keep important cultural differences visible.'),
mk('comparing two quest stories from different countries','Both protagonists face tests on a journey, but the helpers and values celebrated in each story differ.','The stories are identical because they both have a journey.','Only the length of the books can be compared.','A strong comparison links plot patterns to the different ideas or values they express.','Move beyond surface features to what the events suggest.'),
mk('comparing an older fairy tale with a recent graphic novel adaptation','The adaptation keeps the central conflict but uses panels, modern dialogue and a changed ending.','The texts cannot be compared because one uses pictures.','The graphic novel must have exactly the same effect as the older tale.','Form and time can change how a familiar storyline is presented and experienced.','Compare both the story pattern and the way it is told.'),
mk('comparing friendship in two stories set in different eras','Both friendships depend on trust, although the characters communicate and solve problems in different ways.','The friendships are unrelated because the technology is different.','The only important similarity is that both books have two characters.','The comparison focuses on the relationship while recognising how context changes its expression.','Use a shared idea as the anchor, then examine differences.') ]},
AC9E4LE02:{t:'Responding to Literature',s:'explain how literary structures and language features shape a reader’s response',x:[
mk('a story that begins with the ending and then returns to earlier events','The flashback makes me curious about how the characters reached the opening moment.','The story has no structure because time changes.','The only effect is that the text becomes longer.','A flashback changes the order of events and can create curiosity by withholding causes.','Name the feature and connect it to your response.'),
mk('a scene using short sentences during a chase','The short sentences speed the pace and increase tension.','Short sentences always make a scene calm.','Sentence length never affects a reader.','Rapid sentence boundaries can make action feel urgent.','Explain how the language choice changes pace or feeling.'),
mk('a poem repeating the words “still we wait”','The repetition emphasises patience and makes the waiting feel important.','The repeated words have no effect because they are the same.','Repetition only fixes spelling.','Repeated wording can foreground an idea and create rhythm.','Ask why the writer wants the reader to notice these words again.'),
mk('a story resolving its main conflict in the final paragraph','The resolution gives a sense of closure because the central problem is settled.','The resolution creates the complication.','A resolution is only the title.','The resolution stage shows what happens to the central problem.','Link the structural stage to the feeling it creates.'),
mk('a paragraph describing a dark, silent house before a character enters','The sensory details create an uneasy mood before anything happens.','The description proves the house is dangerous.','Description cannot influence mood.','Language can prepare a reader emotionally without proving what will happen.','Separate the effect on the reader from a claim that the text has not established.'),
mk('dialogue interrupted by dashes and unfinished sentences','The broken dialogue suggests hesitation or stress and makes the exchange feel tense.','The punctuation means the characters are singing.','The dialogue is objective factual reporting.','Interrupted speech can reveal emotion and alter the rhythm of the scene.','Use a precise literary term, then explain its effect.'),
mk('a chapter ending just as a door begins to open','The cliffhanger delays the answer and encourages the reader to continue.','The ending fully resolves every question.','The door has no structural role because it is an object.','A cliffhanger withholds an outcome at a key point to build anticipation.','Focus on what information is deliberately delayed.') ]},
AC9E4LE03:{t:'Engaging Stories: Character, Setting and Plot',s:'explain how story elements work together to engage readers',x:[
mk('a character who returns a lost wallet even though they need money','The choice shows honesty and creates interest because doing the right thing costs the character something.','The choice reveals nothing about character.','The wallet matters only because it is an object.','Character is often revealed through choices, especially when there is a consequence or conflict.','Ask what the action shows about the person.'),
mk('a storm approaching while two characters are stranded on a jetty','The threatening setting increases tension because the danger is getting closer.','The setting cannot affect the plot.','Storms always make stories funny.','Setting can create pressure that shapes what characters must do next.','Connect the place or conditions to the problem.'),
mk('two friends arguing in dialogue before a difficult decision','The dialogue reveals their different views and makes the decision more uncertain.','Dialogue only tells readers who is speaking.','The argument removes all conflict.','Dialogue can expose character motives and increase tension in the plot.','Look at what the words reveal about each character.'),
mk('an illustration showing a tiny character beneath a huge cliff','The scale makes the challenge look difficult and the character seem vulnerable.','The picture proves the character will fail.','Illustrations never add to a written story.','Visual choices can reinforce setting and the difficulty of a challenge without deciding the outcome.','Use details from both image and story.'),
mk('a character ignores a warning and later becomes lost','The consequence grows from the earlier choice, linking character action to plot development.','The warning and getting lost are unrelated.','Consequences only happen at the end of stories.','Engaging plots often develop because characters make choices that have effects.','Trace cause and effect through the character’s decision.'),
mk('a mystery story slowly revealing footprints, a broken latch and a missing key','The clues build curiosity because each detail narrows what might have happened.','The clues resolve the mystery immediately.','Details cannot shape tension.','Gradual clues keep readers forming and revising predictions.','Ask what the reader knows now and what is still uncertain.'),
mk('a shy character finally speaks at a community meeting','The moment is engaging because it completes a change the story has been building toward.','The scene is important only because it has speech marks.','Character growth cannot affect reader response.','A significant action can show development and provide a satisfying turning point.','Connect the final action to earlier behaviour.') ]},
AC9E4LE04:{t:'Wordplay and Literary Language',s:'explain how wordplay, poetic and emotive language shape meaning and response',x:[
mk('the pun “The bicycle was two-tired to continue”','The humour comes from two-tired sounding like too tired while also referring to two tyres.','The humour comes from the sentence being factual.','Two-tired is a standard scientific term.','A pun depends on two meanings or similar sounds being activated at once.','Look for the double meaning.'),
mk('the invented word “splish-splashy” in a beach poem','The neologism blends familiar sound patterns to make the water feel lively and playful.','The word has no effect because it is not in every dictionary.','Invented words can only be spelling mistakes.','Writers can create new words to produce a particular sound, image or mood.','Ask what the new word makes you hear or imagine.'),
mk('the line “The wind whispered through the grass”','Personification gives the wind a human action and creates a gentle sound image.','The line reports an exact weather measurement.','Whispered means the grass is speaking literally.','Personification can make a natural element feel alive and shape mood.','Identify the human action and its effect.'),
mk('the phrase “a mountain of homework”','The exaggeration emphasises that the amount feels very large.','The phrase proves the homework is physically a mountain.','The phrase makes the amount smaller.','Hyperbole exaggerates for emphasis rather than literal accuracy.','Check whether the image is meant literally.'),
mk('the emotive phrase “helpless joey” in a rescue appeal','Helpless encourages concern and makes readers feel the animal needs protection.','The word gives only a measurement.','Emotive language removes all viewpoint.','Emotive words are chosen partly for the feelings they encourage.','Notice the feeling carried by the adjective.'),
mk('the simile “the creek glittered like scattered coins”','The comparison helps the reader picture bright flashes of light on the water.','The creek contains actual coins.','The simile explains the creek’s depth exactly.','A simile connects one image to another to create a vivid picture.','Ask what shared quality links the two things.'),
mk('the alliterative phrase “crackling campfire”','The repeated hard c sound draws attention to the phrase and echoes the sharp sound of fire.','Alliteration changes the campfire into a person.','Repeated sounds have no effect on rhythm.','Sound patterns can reinforce an image and make wording memorable.','Listen for repeated starting sounds and connect them to meaning.') ]},
AC9E4LE05:{t:'Creating Literary Texts',s:'develop storylines, characters and settings using purposeful literary choices',x:[
mk('opening a story about a child lost at the Royal Easter Show','Mina checked the map again, but the bright crowd had already swallowed the path to Gate 3.','Mina was at a show. It was a show.','This story will have a complication later because stories do.','The opening establishes a character, setting and immediate problem through action.','Begin with concrete story details rather than explaining the plan for the story.'),
mk('developing a nervous character before a school performance','Backstage, Leo rubbed his palms on his costume and counted each breath.','Leo was nervous nervous nervous.','Leo is a character in this story.','Actions and physical details show the feeling instead of simply labelling it.','Show the emotion through what the character does or notices.'),
mk('creating a vivid bush setting','Dry leaves crackled underfoot while cockatoos screeched above the pale trunks.','The bush was nice and there were trees.','There was a setting in the bush.','Specific sensory details help the reader picture and hear the setting.','Choose concrete nouns and precise verbs.'),
mk('using dialogue to increase tension','“Did you hear that?” Amira whispered. “It came from inside the shed.”','Amira said hello and then nothing changed.','“I am increasing the tension now,” Amira explained.','Dialogue can reveal fear and introduce new information without telling the reader what effect to feel.','Let the characters’ words move the story forward.'),
mk('revising a flat complication','The creek rose over the stepping stones just as the group realised the bridge was behind them.','There was a problem.','Everything went perfectly, so the complication was finished before it began.','A complication creates a specific obstacle that requires the characters to respond.','Make the problem concrete and connected to the setting.'),
mk('ending a story after a lost dog is found','When Tilly heard the familiar collar jingle, she dropped to her knees and hugged Rusty while the whole street cheered.','The dog was found. The end.','Suddenly a spaceship arrived for no reason.','The ending resolves the main problem and gives a final emotional moment tied to the story.','Resolve what the story has been building, rather than adding an unrelated event.'),
mk('giving useful feedback on a classmate’s story','The setting is clear; adding what the character hears at the station could make the tense scene even stronger.','It is bad.','Make every sentence longer.','Useful feedback names what works and suggests one specific change that supports the writer’s purpose.','Be specific about the effect of the suggested revision.') ]},
AC9E4LY01:{t:'Texts Across Time',s:'compare texts with similar purposes and audiences from different times',x:[
mk('comparing an old printed train timetable with a current transport app','Both help travellers plan journeys, but the app can update delays instantly and offer route choices.','They have completely different purposes because one is digital.','The old timetable is automatically less accurate in every detail.','The purpose is similar, while technology changes how current information can be presented and updated.','Compare purpose first, then how context or technology changes the text.'),
mk('comparing a wartime letter with a present-day video message between family members','Both maintain family connection, but the speed, privacy and amount of visual information differ.','They cannot be compared because one has moving images.','The video message proves modern families care more.','Communication technologies change how relationships can be represented without changing the basic purpose of staying connected.','Avoid judging people; compare what the medium allows.'),
mk('comparing an old newspaper sports report with a live online match blog','Both inform audiences about the game, but the live blog updates events as they happen.','Only the online text has an audience.','The old report cannot contain facts.','Publication timing and technology affect immediacy and structure.','Notice when the audience receives the information.'),
mk('comparing a historical tourism poster with a current tourism webpage','Both persuade people to visit, but the webpage can use video, links and booking tools.','The poster is not persuasive because it is old.','The webpage has no visual design.','Similar persuasive purposes can be achieved with different available technologies.','Compare the purpose and the resources each medium uses.'),
mk('comparing an old school rule notice with a current parent portal message','Both communicate expectations, but the portal can link to more information and receive responses.','The old notice has no purpose.','Digital messages always use informal language.','Technology can change interaction and navigation while the underlying informative purpose remains.','Look at what readers can do with each text.'),
mk('comparing a printed emergency leaflet with a current emergency alert','Both give safety instructions, but the alert can be sent quickly to people in a specific area.','The leaflet cannot contain urgent information.','The alert needs no clear wording because it is digital.','Historical and technological context affects delivery, not the need for clear safety information.','Separate delivery method from purpose.'),
mk('comparing an early wildlife field guide with a modern interactive species guide','Both help identify species, but the interactive guide can include calls, zoomable images and updated maps.','The field guide and app have unrelated audiences.','Only the app can use scientific vocabulary.','New technology can extend how similar information is represented and accessed.','Compare shared purpose and changed features.') ]},
AC9E4LY02:{t:'Interacting and Listening',s:'listen for key information, clarify ideas and build on others’ contributions',x:[
mk('following group instructions to make a model bridge','First collect four craft sticks, then tape them into a square.','Start building anything before the instructions finish.','Ignore the sequence and ask what the task is later.','Listening for the key action and order helps complete the task accurately.','Identify the action words and sequence.'),
mk('responding to a classmate who suggests planting native shrubs','That could provide habitat. We could also choose species that need less water.','No, my idea is better.','Anyway, I want to talk about lunch.','The response acknowledges the idea and adds a connected contribution.','Build from what was just said.'),
mk('clarifying an unclear direction during sport','Do you mean we run to the cone first, then pass the ball?','I will just guess what you mean.','Can you repeat everything from the start even though only one step is unclear?','A focused clarifying question checks the uncertain part without derailing the task.','Ask exactly what you need to know.'),
mk('summarising a partner’s suggestion before replying','So you think we should move the display near the entrance because more people will see it.','You said something about a display.','I did not listen, but here is my plan.','Restating the key idea and reason shows accurate listening before adding a response.','Capture the main point, not every word.'),
mk('joining a discussion about reducing food waste','I agree that smaller servings could help. What could we do with unopened food?','That is boring. Next topic.','I agree, because I want to speak now.','The response stays on topic, acknowledges a contribution and asks a useful question.','Connect your question to the group’s current idea.'),
mk('checking details for a museum task','Just to check: we need one sketch and two facts about the object, right?','I will do whatever I remember.','What are we doing? even though the instructions were clear except for the required number.','The question verifies the key requirements needed to complete the task.','Listen for numbers, sequence and required products.'),
mk('disagreeing during a planning discussion','I understand your reason. I think the second option may be safer because it keeps people away from the road.','That idea is stupid.','No. Mine wins.','Respectful disagreement acknowledges the other idea and gives a relevant reason.','Challenge the idea, not the person.') ]},
AC9E4LY03:{t:'Purpose and Features of Texts',s:'identify how text features help imaginative, informative and persuasive texts achieve purpose',x:[
mk('a persuasive poster asking families to walk to school','Use a clear call to action, reasons, emotive wording and a striking image of a safe walking group.','Use only a list of random street names.','Hide the request in tiny print.','Persuasive features work together to influence the audience toward an action.','Ask what the creator wants the audience to think or do.'),
mk('an information page about platypuses','Use headings, factual paragraphs, labelled images and technical vocabulary explained for readers.','Use a cliffhanger ending with no facts.','Use only commands telling readers what to believe.','Informative features organise and explain knowledge.','Look for evidence, clear organisation and subject vocabulary.'),
mk('an imaginative story about a robot on Mars','Use characters, setting, a developing problem and descriptive language.','Use only a contents page and data table.','Give a list of instructions for repairing a toaster.','Imaginative texts develop events and experiences rather than mainly explaining facts or arguing a case.','Identify the main purpose of the whole text.'),
mk('a website encouraging donations to an animal shelter','Use a headline, reasons for donating, selected facts and an easy-to-find Donate link.','Use only neutral measurements with no request.','Place the donation link where readers cannot find it.','Persuasive digital texts combine language and navigation to support the desired action.','Consider both wording and layout.'),
mk('a science infographic about the water cycle','Use labelled stages, arrows, brief explanations and key terms such as evaporation and condensation.','Use an unrelated character conflict.','Replace labels with decorative patterns that carry no information.','Visual organisation can show a process efficiently when labels and arrows carry meaning.','Check how words and graphics share the information.'),
mk('a narrative comic about a lost skateboard','Use panel sequence, dialogue, facial expressions and a clear complication.','Use a bibliography as the main structure.','Use random panels with no sequence.','Panels and images work with language to develop the imaginative sequence.','Follow how meaning moves from one panel to the next.'),
mk('a letter arguing for more trees in the playground','State the request, give reasons and evidence, and finish with a clear recommendation.','Tell an unrelated fantasy story instead of making the case.','List tree species without explaining the request.','A persuasive structure makes the position and supporting reasons easy to follow.','Locate the claim, support and requested action.') ]},
AC9E4LY04:{t:'Fluent Reading',s:'combine decoding, vocabulary, grammar and text knowledge to read complex texts accurately and fluently',x:[
mk('reading “The hikers cautiously crossed the suspension bridge”','Group “cautiously crossed” smoothly and use the sentence meaning to confirm the words.','Read every letter as a separate sound and ignore the sentence.','Replace cautiously with quickly because it is shorter.','Fluent reading coordinates word recognition with grammar and meaning.','Check whether the words you read make sense in the sentence.'),
mk('meeting the unfamiliar word “reusable”','Use the parts re- + use + -able and the sentence context to work out “able to be used again”.','Guess from the first letter only.','Skip the word and continue without checking meaning.','Morphology and context can work together to identify and understand a multisyllabic word.','Break the word into meaningful parts.'),
mk('reading a paragraph with commas around an extra detail','Pause lightly around the extra detail but keep the sentence flowing.','Stop for several seconds at every comma.','Ignore all punctuation and read in one flat rush.','Punctuation guides phrasing, but fluent reading keeps connected ideas together.','Use punctuation to shape meaning, not to chop the text into pieces.'),
mk('realising a sentence no longer makes sense after reading a word incorrectly','Go back, reread the phrase and correct the word using letters and context.','Keep going even though the sentence makes no sense.','Change several other words to fit the mistake.','Monitoring meaning helps readers notice and repair decoding errors.','A self-correction should fit both the print and the sentence meaning.'),
mk('reading a factual paragraph about cyclones','Use the heading and topic vocabulary to anticipate likely meanings while still checking every printed word.','Say any weather word that seems possible without looking closely.','Ignore the heading and technical terms.','Topic knowledge supports prediction, but accurate reading still depends on the text.','Use knowledge to support, not replace, decoding.'),
mk('reading dialogue between two characters','Use punctuation and reporting clauses to change phrasing slightly for each speaker while keeping the words accurate.','Read quotation marks aloud as words.','Ignore who is speaking.','Fluent phrasing reflects sentence structure and speaker changes.','Track quotation marks, speech tags and sentence boundaries.'),
mk('reading a long sentence with a dependent clause first','Read the opening dependent clause as one phrase, then continue into the main clause.','Stop permanently after the dependent clause.','Treat every word as an unrelated unit.','Recognising clause structure helps readers group words into meaningful phrases.','Find the clause boundary before deciding where to pause.') ]},
AC9E4LY05:{t:'Comprehension Strategies',s:'build literal and inferred meaning, identify evidence and evaluate reasoning across modes',x:[
mk('inferring why a character grabs an umbrella after seeing black clouds','The character probably expects rain because the dark clouds are a clue and the umbrella connects to wet weather.','The text proves a cyclone will occur.','The character dislikes umbrellas.','An inference combines a text clue with relevant knowledge without claiming more than the evidence supports.','Name the clue and the knowledge you used.'),
mk('finding the main idea of a paragraph about mangrove roots, mud and fish nurseries','Mangroves create important habitat in coastal wetlands.','Mangrove roots are brown.','One fish swam past a root.','The main idea connects several supporting details rather than repeating one small fact.','Ask what most of the details are explaining.'),
mk('summarising a short article about recycling batteries','Batteries contain materials that can be recovered, so they should go to special collection points rather than household bins.','Batteries. Collection. Bins.','Copy every sentence from the article.','A summary keeps the central ideas and removes unnecessary detail.','State the key message in fewer words.'),
mk('evaluating the claim “Our canteen should sell only fruit because one student likes apples”','The evidence is too weak because one student’s preference does not show what the whole school needs.','The claim is proven because any example counts as enough evidence.','The claim must be true because fruit is mentioned.','Evidence should be relevant and strong enough for the size of the claim.','Ask whether the evidence represents the people or issue being discussed.'),
mk('combining a map, caption and paragraph about a bushfire','Use the map for location, the caption for what the image shows and the paragraph for the explanation, then connect the information.','Read only the largest element and ignore the others.','Assume colours mean the same thing without checking the legend.','Multimodal comprehension combines information carried by words, images and symbols.','Use each mode for the information it contributes.'),
mk('checking a prediction halfway through a mystery story','Revise the prediction if new clues no longer support it.','Keep the first prediction no matter what the text says.','Choose a new prediction randomly.','Good readers monitor predictions against new evidence.','Predictions are working ideas, not fixed answers.'),
mk('asking a useful question while reading an argument about school uniforms','What evidence does the writer give that uniforms save families money?','What is my favourite colour?','How many letters are in the title?','A useful comprehension question targets the writer’s claim, evidence or reasoning.','Ask something that helps test or deepen understanding of the text.') ]},
AC9E4LY06:{t:'Creating Written Texts',s:'plan, draft and edit coherent texts with paragraphs, complex sentences and precise language',x:[
mk('planning an information report about wombats','Group notes into sections such as habitat, diet and behaviour before drafting.','Write every fact in the order it was found.','Start drafting unrelated sentences without deciding the purpose.','Planning related ideas into sections creates a clear basis for paragraphs.','Sort ideas by topic before writing full sentences.'),
mk('building a paragraph about water saving','Start with the main point, add linked examples and use connectives such as for example and therefore where they fit.','Put one sentence about water between two sentences about football.','Add however to every sentence whether or not there is a contrast.','A coherent paragraph keeps one main focus and uses connectives for real relationships.','Check both topic unity and logical links.'),
mk('combining ideas into a complex sentence','Because the tank was nearly empty, the family shortened their showers.','Because the tank was nearly empty.','The family shortened because tank showers.','The dependent cause clause adds a reason to a complete main clause.','Check that one clause can stand alone and the other adds a relationship.'),
mk('editing tense in a recount','We arrived at the campsite, unpacked the car and cooked dinner.','We arrived at the campsite, unpack the car and will cook dinner yesterday.','We arriving at the campsite and cooked tomorrow.','Consistent past tense suits events that happened during the same past time frame.','Only shift tense when the time frame changes.'),
mk('replacing vague vocabulary in a science explanation','The metal expanded when it was heated.','The metal did something when it got hot.','The metal became nice.','Expanded precisely names the change and suits the scientific purpose.','Choose the most exact word for the meaning.'),
mk('editing a multisyllabic word and punctuation','The environmental program begins on Wednesday, and families can register online.','The enviromental program begins on Wednesday and families can regester online','The environmental program begins on Wednesday and, families can register online.','Editing checks spelling patterns and punctuation as well as ideas.','Read for one feature at a time: spelling, sentence boundary, then punctuation.'),
mk('writing a conclusion to a persuasive text about a bike rack','For these reasons, a covered bike rack would make cycling to school safer and more practical.','Bikes have wheels.','Now I will introduce a completely different issue.','The conclusion returns to the position and synthesises the reasons instead of adding a new topic.','Finish by reinforcing the main case.') ]},
AC9E4LY07:{t:'Presentations',s:'plan and deliver structured presentations using suitable evidence, language, visuals and voice',x:[
mk('opening a talk about local frog habitats','Today I will explain where local frogs live, what threatens them and how we can help.','Um, frogs. I guess I will say stuff.','I will begin with my final detail and never explain the topic.','A clear opening previews the topic and structure for the audience.','Tell listeners what they are about to learn.'),
mk('supporting a claim in a presentation about litter','Use a council clean-up figure and explain how it supports the point about litter in local parks.','Say everyone knows litter is terrible.','Use an unrelated fact about rainfall.','Reliable, relevant evidence strengthens a claim when the link is explained.','Evidence must connect directly to the point.'),
mk('choosing language for a factual science presentation','The water temperature increased by 4°C during the test.','The water became super awesome hot.','I feel the temperature was probably the best.','Objective language suits a factual report of measured results.','Match subjective or objective wording to the presentation purpose.'),
mk('using a slide about the solar system','Show one clear labelled diagram while explaining the key relationships aloud.','Fill the slide with tiny paragraphs and read every word.','Use a decorative image that has no connection to the explanation.','A visual should extend or clarify the spoken message rather than compete with it.','Ask what the audience needs to see while listening.'),
mk('speaking to a large assembly','Use enough volume to be heard, a steady pace and pauses at key points.','Rush quietly through every sentence.','Shout every word at the same pitch.','Controlled volume, pace and pauses make meaning easier to follow.','Voice choices should support understanding, not simply make speech louder.'),
mk('presenting a recommendation to the school council','State the recommendation, give two strong reasons with evidence, then finish with the action requested.','List unrelated facts with no recommendation.','Give the requested action before explaining the topic and never return to it.','A persuasive presentation needs a visible line from position to reasons to requested action.','Make the structure easy for listeners to follow.'),
mk('answering a question after a presentation','Pause, answer the exact question and refer back to evidence from the talk if useful.','Repeat the entire presentation regardless of the question.','Guess confidently even when you do not know.','A focused response respects the audience and keeps the discussion connected to the presentation.','Listen for what is actually being asked.') ]},
AC9E4LY08:{t:'Handwriting Fluency',s:'form joined letters clearly and fluently while keeping writing readable',x:[
mk('writing the word “making” in joined handwriting','Use smooth joins where appropriate while keeping each letter recognisable.','Join every stroke into one tangled shape.','Lift the pencil after every tiny stroke even when a natural join is possible.','Fluent handwriting balances efficient movement with clear letter shapes.','Speed only helps if the writing remains easy to read.'),
mk('keeping letter size consistent in a sentence','Keep lower-case letters a similar body height and make tall letters clearly taller.','Make each letter a random size.','Write all letters at the same height including capitals and ascenders.','Consistent proportions improve readability and support automatic writing.','Compare body letters, tall letters and capitals.'),
mk('spacing words in joined handwriting','Leave a clear, consistent gap between words while keeping joined letters within a word close together.','Join the last letter of one word to the first letter of the next.','Put huge gaps between letters inside each word.','Word spacing helps readers see where one word ends and the next begins.','Spacing should show word boundaries.'),
mk('writing quickly during a short note-taking task','Use a comfortable grip and efficient joins without sacrificing recognisable letters.','Press as hard as possible and scribble faster.','Ignore line direction so the words overlap.','Fluency comes from controlled, automatic movement rather than force or careless speed.','Aim for smoothness and legibility together.'),
mk('checking a handwritten paragraph','Rewrite any word whose joins or letter shapes make it hard to read.','Keep unclear words because handwriting never needs editing.','Add more loops to every letter whether needed or not.','Legibility is the test of whether a handwriting choice is working.','Read your own writing as if you were another reader.'),
mk('joining after the letter o','Use the taught exit stroke so the next letter begins from a natural position.','Invent a new loop that crosses through the previous letter.','Make the join so high that the next letter is mistaken for a capital.','Consistent join patterns support both speed and recognisable letter formation.','Follow the school’s taught joining pattern rather than adding decoration.'),
mk('writing a heading and body text by hand','Use clear print or larger writing for the heading and fluent joined handwriting for the body if that improves readability.','Use the same cramped size for everything.','Make the heading so decorative that the words cannot be read.','Handwriting choices can vary with purpose while remaining clear.','Format should help readers see the text structure.') ]},
AC9E4LY09:{t:'Morphology and Multisyllabic Words',s:'use sounds, syllables, prefixes, suffixes and meaningful word parts to read and spell complex words',x:[
mk('working out “unhelpful”','Break it into un- + help + -ful and use the parts to understand “not helpful”.','Guess from the first two letters only.','Treat unhelpful as unrelated to help.','Recognising prefix, base word and suffix supports both decoding and meaning.','Look for a known base word inside the longer word.'),
mk('spelling “careless”','Use care + -less, keeping the base word care before adding the suffix.','Spell it carless because the unstressed vowel seems quiet.','Spell it careluss by sound alone.','Morphological knowledge protects the spelling of the meaningful base even when sounds are reduced.','Think about the base word before the suffix.'),
mk('reading “information”','Chunk the word into manageable syllables and connect inform + -ation to meaning.','Sound out the whole word as one long unit without checking meaning.','Skip the unstressed syllable completely.','Syllable chunking and morphology can work together in long words.','Find both pronounceable chunks and meaningful parts.'),
mk('spelling “disagreement”','Build it from dis- + agree + -ment.','Spell it disagreemint only from the weak final vowel.','Remove agree because the prefix changes the whole word.','The known morphemes preserve spelling even when an unstressed vowel is hard to hear.','Write the meaningful parts you know.'),
mk('working out “reappearance”','Recognise re- + appear + -ance and connect the word to appearing again.','Assume re- always means wrong.','Treat the word as having no connection to appear.','Prefixes and suffixes provide clues to both pronunciation and meaning.','Start with the base word and then add each affix meaning.'),
mk('reading “environmental”','Use syllables en-vi-ron-men-tal and recognise environment + -al.','Guess the word from the picture only.','Ignore the final suffix and pronounce every vowel strongly.','Long words often become easier when readers combine syllable knowledge with a familiar base and suffix.','Do not rely on one strategy alone.'),
mk('spelling “musician”','Connect music to musician and remember the -cian ending used in this word family.','Spell it muzishun only from the sounds.','Drop the link to music because the pronunciation changes.','Word families and morphemes explain spellings that are not fully predictable from sound alone.','Ask which known word is inside the longer word.') ]},
AC9E4LY10:{t:'Spelling Patterns and Word Origins',s:'use letter patterns, affixes, word families and origins to spell complex words',x:[
mk('spelling “running”','Double the final n in run before adding -ing: running.','Write runing.','Write runnning.','A short stressed vowel followed by one final consonant often triggers doubling before a vowel suffix.','Check the base word ending before adding the suffix.'),
mk('spelling “hopeful”','Keep the e in hope before adding -ful: hopeful.','Write hopful.','Write hopefull.','The suffix -ful is spelled with one l, and the base word hope stays recognisable.','Think about both the base word and the suffix spelling.'),
mk('spelling “happiness”','Change happy to happi- before adding -ness: happiness.','Write happyness.','Write hapiness.','Words ending in consonant + y often change y to i before a suffix such as -ness.','Apply the spelling generalisation to the base word.'),
mk('choosing a word from the “sign” family','The g is kept in signature even though the pronunciation changes.','Remove the g from every word in the family.','Spell each family member only by how it sounds today.','Word origins and families can explain letters that are not obvious from pronunciation.','Compare related words to uncover spelling clues.'),
mk('spelling “carefully”','Build careful + -ly: carefully.','Write carefuly.','Write carefullly.','The word is built from care + -ful + -ly, so recognising suffixes prevents random doubling.','Build the word one morpheme at a time.'),
mk('spelling “knitted”','Double the final t in knit before adding -ed: knitted.','Write knited.','Write knittted.','The short stressed vowel and final single consonant trigger doubling before -ed.','Say the base word, inspect its ending, then add the suffix.'),
mk('checking the spelling of “telephone”','Use knowledge that tele- means distant and phone relates to sound, then confirm the familiar letter pattern.','Spell it tellefone only from the sounds.','Change ph to f in every related word.','Word origins can explain stable letter patterns such as ph representing /f/.','Use origin or word-family knowledge when sound alone is not enough.') ]},
AC9E4LY11:{t:'High-Frequency Words and Homophones',s:'choose the correct spelling of common words and homophones using grammar and context',x:[
mk('completing “_____ going to the pool after lunch.”','They’re','Their','There','They’re means they are and fits before the verb going.','Expand the contraction to test whether it fits.'),
mk('completing “Please put the bags over _____.”','there','their','they’re','There refers to a place, which matches where the bags should go.','Decide whether the sentence needs a place, ownership or they are.'),
mk('completing “The players packed _____ uniforms.”','their','there','they’re','Their is the possessive form showing that the uniforms belong to the players.','Look for a noun that is owned by someone.'),
mk('completing “I can _____ the kookaburras calling.”','hear','here','he’re','Hear is the verb meaning perceive sound.','Use sentence grammar and meaning, not just pronunciation.'),
mk('completing “Come and sit _____ beside me.”','here','hear','heer','Here refers to this place.','Ask whether the word names a place or an action involving sound.'),
mk('completing “The dog wagged _____ tail.”','its','it’s','its’','Its shows possession, while it’s means it is or it has.','Expand it’s to it is and see whether that makes sense.'),
mk('completing “_____ been raining since breakfast.”','It’s','Its','Its’','It’s is the contraction of it has in this sentence.','Try expanding the contraction before choosing the spelling.') ]}
};

const codes=Object.keys(P);
const stages=['recognise','explain','discriminate','apply'];
const starters={
recognise:[x=>`In ${x.c}, which option best demonstrates the skill?`,x=>`Which choice fits ${x.c} most accurately?`,x=>`Look closely at ${x.c}. Which response or wording works best?`,x=>`For ${x.c}, which option is the strongest match?`,x=>`Which example should you choose for ${x.c}?`],
explain:[x=>`Why does “${x.g}” work well for ${x.c}?`,x=>`What makes “${x.g}” a better choice in ${x.c}?`,x=>`Which explanation best justifies “${x.g}” for ${x.c}?`,x=>`What should you notice about “${x.g}” in ${x.c}?`,x=>`Which reason explains why “${x.g}” suits ${x.c}?`],
discriminate:[x=>`Which revision best fixes the problem in “${x.b}” for ${x.c}?`,x=>`Compare the choices for ${x.c}. Which one avoids the mistake in “${x.b}”?`,x=>`If “${x.b}” does not work in ${x.c}, what should replace it?`,x=>`Which option corrects the meaning or form needed for ${x.c}?`,x=>`Which choice is the clearest correction for ${x.c}?`],
apply:[x=>`You now need to handle ${x.c} independently. Which choice should you use?`,x=>`Apply the same idea to ${x.c}. Which option is best?`,x=>`Which decision would produce the clearest result in ${x.c}?`,x=>`Choose the option that applies the skill correctly in ${x.c}.`,x=>`What would be the most effective choice for ${x.c}?`]
};
const norm=s=>String(s).replace(/\s+/g,' ').trim().toLowerCase();
function answers(correct,wrong,seed){const ci=seed%3,a=[...wrong];a.splice(ci,0,correct);return{answers:a.map((text,i)=>({text,is_correct:i===ci})),correct_index:ci};}
function item(code,p,x,n,stage,q,correct,wrong,summary,hint,bank){const a=answers(correct,wrong,n+codes.indexOf(code)+(bank==='test'?1:0));return{id:`${code}-${bank==='test'?'T':'P'}-${String(n+1).padStart(3,'0')}`,subject:'english',year_level:'Year 4',curriculum_code:code,bank,stage,skill:p.t,question:q,audio_prompt:q,...a,explanation:{summary,hint}};}
function makePractice(code,p){const out=[];for(let si=0;si<4;si++){const stage=stages[si];for(let ci=0;ci<5;ci++){const x=p.x[ci];for(let j=0;j<2;j++){const n=si*10+ci*2+j;let q,correct,wrong,summary,hint;if(stage==='recognise'){q=starters.recognise[(ci+j)%5](x);correct=x.g;wrong=[x.b,x.d];summary=x.r;hint=x.h;}else if(stage==='explain'){q=starters.explain[(ci+j)%5](x);correct=x.r;wrong=[`Because “${x.b}” is always acceptable in this situation.`,`Because the longest or most complicated option must be correct.`];summary=x.r;hint=x.h;}else if(stage==='discriminate'){q=starters.discriminate[(ci+j)%5](x);correct=x.g;wrong=[x.b,x.d];summary=`${x.r} A common mistake is to choose wording or form that only looks familiar instead of checking the exact meaning and situation.`;hint=x.h;}else{q=starters.apply[(ci+j)%5](x);correct=x.g;wrong=[x.d,x.b];summary=x.r;hint=x.h;}out.push(item(code,p,x,n,stage,q,correct,wrong,summary,hint,'practice'));}}}return out;}
function makeTest(code,p){const out=[];for(let ci=5;ci<7;ci++){const x=p.x[ci];const qs=[`New context: ${x.c}. Which option is correct?`,`What is the best choice for ${x.c}?`,`Which explanation best supports “${x.g}” in ${x.c}?`,`Which clue should guide your decision in ${x.c}?`,`Which option would you reject first in ${x.c}?`,`Which correction should replace “${x.b}” in ${x.c}?`,`Apply the skill to ${x.c}: what should you choose?`,`Which final choice gives the clearest and most accurate result for ${x.c}?`];for(let j=0;j<8;j++){const n=(ci-5)*8+j;let c,w,s,h;if(j===2){c=x.r;w=[`Because “${x.b}” is always a safe choice.`,`Because surface appearance matters more than meaning.`];s=x.r;h=x.h;}else if(j===3){c=x.h;w=['Choose the option with the most words.','Ignore the context and use the first familiar form.'];s=x.r;h=x.h;}else if(j===4){c=x.b;w=[x.g,x.d];s=`The rejected choice conflicts with the exact meaning, form or situation being tested. ${x.r}`;h=x.h;}else{c=x.g;w=[x.b,x.d];s=x.r;h=x.h;}out.push(item(code,p,x,n,j<4?'verify':'apply',qs[j],c,w,s,h,'test'));}}return out;}
for(const code of codes){const p=P[code];if(p.x.length!==7)throw Error(`${code}: expected 7 authored contexts`);const practice=makePractice(code,p),test=makeTest(code,p);if(practice.length!==40||test.length!==16)throw Error(`${code}: bad counts`);const ps=new Set(practice.map(x=>norm(x.question))),ts=new Set(test.map(x=>norm(x.question)));if(ps.size!==40||ts.size!==16)throw Error(`${code}: duplicate stems`);if(test.some(x=>ps.has(norm(x.question))))throw Error(`${code}: practice/test overlap`);for(const q of [...practice,...test]){if(q.answers.length!==3||q.answers.filter(a=>a.is_correct).length!==1||q.correct_index<0||q.correct_index>2)throw Error(`${q.id}: answer integrity`);if(/\bA Year 4 student\b|\brubric\b|\bteacher should\b|\bmarking key\b/i.test(q.question))throw Error(`${q.id}: banned wording`);}fs.writeFileSync(path.join(OUT,`${code.toLowerCase()}.json`),JSON.stringify([...practice,...test],null,2)+'\n');}
console.log(`Year 4 English actual rebuild: ${codes.length} codes, ${codes.length*40} practice, ${codes.length*16} separate test, ${codes.length*56} total.`);
